async function(path,expected){
 const hh=load("pure_helpers_json").helpers;
 const utf8=new Function("return ("+hh.utf8+")")(),sha256=new Function("return ("+hh.sha256Bytes+")")(),sha1=new Function("return ("+hh.sha1Bytes+")")();
 const size=expected.bytes;
 const reads=await Promise.allSettled(Array.from({length:Math.ceil(size/65536)},(_,i)=>tools.exec_command({cmd:`python - <<'PY'\nfrom pathlib import Path\nimport sys\nsys.stdout.write(Path('${path}').read_bytes()[${i*65536}:${Math.min((i+1)*65536,size)}].decode('utf-8'))\nPY`,shell:"bash",login:false,max_output_tokens:50000})));
 let content="";for(let i=0;i<reads.length;i++){const r=reads[i];if(r.status!=="fulfilled"||r.value.exit_code!==0)throw Error("local read "+i+" "+path);content+=r.value.output;}
 const bytes=utf8(content),blob=sha1([...utf8("blob "+bytes.length+"\0"),...bytes]);
 if(bytes.length!==size||sha256(bytes)!==expected.sha256||blob!==expected.git_blob)throw Error("local hash mismatch "+path);
 const key="candidate_upload:"+blob;
 let state=load(key);
 if(state?.full_get_verified===true)return state;
 let post;
 if(state?.create_ack===true){
   post={structuredContent:{sha:blob}};
 }else{
   post=await tools.mcp__codex_apps__github_create_blob({repository_full_name:"TrillionniumFoundation/Hepta",encoding:"utf-8",content});
   store(key+":post",post);
   if(post.structuredContent?.sha!==blob)throw Error("create ACK mismatch "+path);
   state={blob,bytes:size,sha256:expected.sha256,path,create_ack:true,full_get_verified:false};
   store(key,state);
   const ackPath=path+".GIT-ACK.json";
   await tools.apply_patch("*** Begin Patch\n*** Add File: "+ackPath+"\n+"+JSON.stringify(state,null,2).replaceAll("\n","\n+")+"\n*** End Patch");
 }
 const fetched=await tools.mcp__codex_apps__github_fetch_blob({repository_full_name:"TrillionniumFoundation/Hepta",blob_sha:blob});
 if(fetched.structuredContent?.content!==content)throw Error("full GET mismatch "+path);
 state={...state,full_get_verified:true};
 store(key,state);
 await tools.apply_patch("*** Begin Patch\n*** Add File: "+path+".GIT-VERIFIED.json\n+"+JSON.stringify(state,null,2).replaceAll("\n","\n+")+"\n*** End Patch");
 return state;
}

